{% load judicialfilters %}

<div class="papper">
    <div>{% include "judicial/lawsuit/header.html" %}</div>

    <h2 class="title-1" style="text-align:center;">{{ doc.codename }}: {{ ordinace.number }}</h2>

    <div class="paragraph-text">
		{{ doc.consideration | safely }}
    </div>

    <ol class="list-numbered">
        <li>
            <span class="title bold">Origem : </span>
            <p>Protocolo de Notícia de Fato número {{ ordinace.document_number }}.</p>
        </li>
        {% if ordinace.blokes %}
        <li>
            <span class="title bold">Investigados :</span>

            <ul class="list-doted">
            {% for bloke in ordinace.blokes %}
                <li>{{ bloke }}</li>
            {% endfor %}
            </ul>
        </li>
        {% endif %}
        <li>
            <span class="title bold">Objeto do procedimento :</span>
            <div class="paragraph-text">
                {{ ordinace.object_of_proccess | safely }}
            </div>
        </li>
        {% if ordinace.legalgrounds %}
        <li>
            <span class="title bold">Fundamentação Legal :</span>
            <ul class="list-doted">
            {% for legalground in ordinace.legalgrounds %}
                <li>{{ legalground }}</li>
            {% endfor %}
            </ul>
        </li>
        {% endif %}
        <li>
            <span class="title bold">Diligências :</span>
            <ol>
            {% if ordinace.diligences %}
            {% for diligence in ordinace.diligences %}
                <li class="paragraph-text">
                    <span class="numbered">{{ ordinace.section }}.{{ forloop.counter }}.</span>
                    {{ diligence.observation | safely }}
                </li>
            {% endfor %}
            {% else %}
                <li>Ainda não foi pedida nenhuma diligencia.</li>
            {% endif %}
            </ol>
        </li>
    </ol>

    {% if doc.attaches.filter %}
        <div style="margin: 2em 0">
            <h3 style="margin-bottom:0.7em">Anexos</h3>
            {% for attach in doc.attaches.filter %}
                <div style="padding:0.5em 0">
                    <a href="{{ attach.file_descriptor.permalink }}" title="{{ attach.title }}">
                        {{ attach.file_descriptor.filename }}
                    </a>
                    <div><small>URL: http://athenas.developer.ti{{ attach.file_descriptor.permalink }}</small></div>
                    <div><small>MD5: {{ attach.file_descriptor.file }}</small></div>
                </div>
            {% endfor %}
        </div>
    {% endif %}

    {% if doc.signed_by %}
		{% with modified_at=doc.signed_at %}
		{% include "judicial/lawsuit/owner_sign.html" %}
		{% endwith %}
	{% endif %}
</div>

